import { useEffect, useState } from 'react'
import styles from './ProductCard.module.css'

export type ProductCardProps = {
    id: string
    title: string
    price: number
    onAdd?: (id: string) => void
}

export default function ProductCard({ id, title, price, onAdd }: ProductCardProps) {
    const [loading, setLoading] = useState(false)
    const [stock, setStock] = useState<number | null>(null)

    useEffect(() => {
        let cancelled = false
        setLoading(true)
        fetch(`/api/products/${id}/stock`)
            .then(r => r.json())
            .then(j => { if (!cancelled) setStock(j.count) })
            .finally(() => { if (!cancelled) setLoading(false) })
        return () => { cancelled = true }
    }, [id])

    return (
        <div className={styles.card}>
            <h3 className={styles.title}>{title}</h3>
            <span className={styles.price}>${price.toFixed(2)}</span>
            {loading ? <span>Loading…</span> : <span>{stock ?? 0} left</span>}
            <button onClick={() => onAdd?.(id)} disabled={!stock}>Add to cart</button>
        </div>
    )
}

